function validate([dist, hour]) {
  if (!Array.isArray(dist) || dist.length < 1 || dist.length > 100000) return 'dist needs 1 to 10^5 rides.';
  if (dist.some(d => !Number.isInteger(d) || d < 1 || d > 100000)) return 'Each distance is an integer from 1 to 10^5.';
  if (typeof hour !== 'number' || hour < 1 || hour > 1e9) return 'hour is between 1 and 10^9.';
  if (Math.abs(hour * 100 - Math.round(hour * 100)) > 1e-6) return 'hour has at most two digits after the decimal point.';
  return null;
}

