function minSpeedOnTime(dist, hour) {
  const n = dist.length;
  const limit = Math.round(hour * 100);
  if (limit <= (n - 1) * 100) {
    return -1;
  }

  const canArrive = (speed) => {
    let whole = 0;
    for (let i = 0; i < n - 1; i++) {
      whole += Math.ceil(dist[i] / speed);
    }
    const spare = limit - whole * 100;
    return 100 * dist[n - 1] <= speed * spare;
  };

  let left = 1;
  let right = 10000000;
  while (left < right) {
    const mid = Math.floor((left + right) / 2);
    if (canArrive(mid)) {
      right = mid;
    } else {
      left = mid + 1;
    }
  }
  return left;
}

