function minSpeedOnTime(dist, hour) {
  const arrival = (speed) => {
    let time = 0;
    for (let i = 0; i < dist.length; i++) {
      if (i > 0) time = Math.ceil(time);
      time += dist[i] / speed;
    }
    return time;
  };
  const onTime = (speed) => arrival(speed) <= hour + 1e-11;
  if (!onTime(10000000)) return -1;
  for (let speed = 1; ; speed++) if (onTime(speed)) return speed;
}

