function generate(rand, size) {
  const n = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 6);
  const top = size === 'large' ? 100000 : 20;
  const dist = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const total = dist.reduce((a, b) => a + b, 0);
  const mode = Math.floor(rand() * 4);
  let hundredths;
  if (mode === 0) {
    // Anywhere from slightly impossible to very relaxed.
    hundredths = (n - 1) * 100 - 100 + Math.floor(rand() * (total * 100 + 300));
  } else if (mode === 1) {
    // Just above the n - 1 whole hours the first rides need: fast trains required.
    hundredths = (n - 1) * 100 + 1 + Math.floor(rand() * 60);
  } else if (mode === 2) {
    // Skewed toward tight but feasible limits.
    hundredths = (n - 1) * 100 + 1 + Math.floor(Math.pow(rand(), 3) * total * 100);
  } else {
    // Exactly the arrival time at some speed, when that time has two decimals.
    const speed = 1 + Math.floor(rand() * (size === 'large' ? 5000 : 12));
    let whole = 0;
    for (let i = 0; i < n - 1; i++) whole += Math.ceil(dist[i] / speed);
    const last = 100 * dist[n - 1];
    hundredths = last % speed === 0 ? whole * 100 + last / speed : whole * 100 + Math.ceil(last / speed);
  }
  hundredths = Math.max(100, Math.min(hundredths, 100000000000));
  return [dist, hundredths / 100];
}
